const t = document.getElementById('inventory-table');
const firstRow = t.rows[0];
const ths = Array.from(firstRow.cells);
if (ths.length !== 5) return false;
const allTh = ths.every(c => c.tagName === 'TH' && c.getAttribute('scope') === 'col');
const classesPreserved = ths.every(c => c.classList.contains('header-style'));
const dataFieldsPreserved = ths[0].dataset.field === 'sku' && ths[1].dataset.field === 'desc' && ths[2].dataset.field === 'cat' && ths[3].dataset.field === 'qty' && ths[4].dataset.field === 'price';
return allTh && classesPreserved && dataFieldsPreserved;

const btn = document.getElementById('sort-price-btn');
if (!btn) return false;
if (btn.closest('th') !== document.querySelector('#inventory-table th.col-price')) return false;
if (btn.getAttribute('aria-label') !== 'Sort by Unit Price') return false;
btn.focus();
if (document.activeElement !== btn) return false;
const rect = btn.getBoundingClientRect();
if (rect.width < 24 || rect.height < 24) return false;
const prevClicks = window.__sortClicked || 0;
btn.click();
const clicked = window.__sortClicked === prevClicks + 1;
btn.blur();
return clicked;

const t = document.getElementById('sales-table');
const thead = t.querySelector('thead');
if (!thead || thead.dataset.ai4a11yGenerated !== 'true') return false;
const ths = Array.from(thead.querySelectorAll('th'));
if (ths.length !== 3) return false;
const allCols = ths.every(c => c.getAttribute('scope') === 'col' && c.textContent.trim() === 'Regional Metric');
const children = Array.from(t.children);
const captionIdx = children.findIndex(c => c.tagName === 'CAPTION');
const colgroupIdx = children.findIndex(c => c.tagName === 'COLGROUP');
const theadIdx = children.findIndex(c => c.tagName === 'THEAD');
const tbodyIdx = children.findIndex(c => c.tagName === 'TBODY');
const validOrder = captionIdx === 0 && colgroupIdx === 1 && theadIdx === 2 && tbodyIdx === 3;
const dataRowsCount = t.querySelector('tbody').rows.length;
return allCols && validOrder && dataRowsCount === 5;

const sup = document.getElementById('suppliers-table');
const specs = document.getElementById('specs-table');
const layout = document.getElementById('layout-table');
if (sup.querySelectorAll('th').length !== 3) return false;
if (sup.querySelectorAll('thead').length !== 1) return false;
if (specs.querySelectorAll('th').length !== 0) return false;
if (layout.querySelectorAll('th').length !== 0) return false;
return true;

const navLinks = document.querySelectorAll('nav a');
const h1 = document.querySelector('header h1');
const footer = document.querySelector('footer');
return navLinks.length === 3 && !!h1 && !!footer;
